"""Generate the research results report and standalone figures."""
import json,html,platform
from pathlib import Path
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from core import PRIMARY,ALL_IF,BASELINES
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'results'
LABEL={'global_mad':'Global MAD','time_of_week_mad':'Time-of-week MAD','pca_reconstruction':'PCA reconstruction',
'sitdd_adapted':'Si-TDD-style (adapted)','if_raw_full':'IF · full windows','if_raw_pca2':'IF · PCA 2','if_raw_pca4':'IF · PCA 4','if_raw_pca6':'IF · PCA 6',
'if_context_full':'Context + IF · full','if_context_pca2':'Context + IF · PCA 2','if_context_pca4':'Context + IF · PCA 4','if_context_pca6':'Context + IF · PCA 6'}

def main():
    p=json.loads((ROOT/'protocol.json').read_text());sel=json.loads((ROOT/'selected_parameters.json').read_text())
    summary=pd.read_csv(OUT/'summary.csv');final=summary.query("role=='final' and label_set=='label_set_1'").set_index('model')
    final2=summary.query("role=='final' and label_set=='label_set_2'").set_index('model');effects=pd.read_csv(OUT/'paired_effects.csv')
    normal=pd.read_csv(OUT/'normal_only_sensitivity.csv');bench=pd.read_csv(OUT/'isolated_benchmark.csv')
    order=BASELINES+ALL_IF
    f=final.reindex(order);fig,ax=plt.subplots(figsize=(11,6));ax.barh([LABEL[k] for k in order],f.f1,color=['#8496a5' if k in BASELINES else '#d26635' if 'context' in k else '#2f7189' for k in order]);ax.invert_yaxis()
    ax.set(xlabel='Mean site F1 · inspector set 1',title='117 final-evaluation road sections · three chronological folds');ax.grid(axis='x',alpha=.15);fig.tight_layout();fig.savefig(OUT/'final_f1.png',dpi=160);plt.close(fig)
    ef=effects.query("label_set=='label_set_1'").iloc[:4];fig,ax=plt.subplots(figsize=(10,4));ax.errorbar(ef.mean_f1_difference,np.arange(len(ef)),
        xerr=np.vstack([ef.mean_f1_difference-ef.ci95_low,ef.ci95_high-ef.mean_f1_difference]),fmt='o',capsize=5,color='#2f7189')
    ax.axvline(0,color='#9aa7b1',linewidth=1);ax.set_yticks(np.arange(len(ef)),ef.comparison);ax.invert_yaxis();ax.set(xlabel='Paired F1 difference · 95% site-bootstrap interval',title='Matched primary effects');ax.grid(axis='x',alpha=.15);fig.tight_layout();fig.savefig(OUT/'paired_effects.png',dpi=160);plt.close(fig)
    curves=pd.read_csv(OUT/'precision_recall_curves.csv');fig,ax=plt.subplots(figsize=(9,5))
    for kind in ['time_of_week_mad','sitdd_adapted',*PRIMARY]:
        g=curves[(curves.model==kind)&(curves.label_set=='label_set_1')];ax.plot(g.recall,g.precision,label=LABEL[kind])
    ax.set(xlabel='Recall',ylabel='Interpolated precision',title='Macro precision–recall curves · final sites');ax.legend(fontsize=9);ax.grid(alpha=.15);fig.tight_layout();fig.savefig(OUT/'precision_recall.png',dpi=160);plt.close(fig)
    # Example selected deterministically by manifest order, not by its performance.
    site=next(r['site'] for r in p['sites'] if r['role']=='final');z=np.load(OUT/'evaluation'/f'{site}_fold2.npz');kind=sel['demo_model'];t=pd.to_datetime(z['timestamps']);key=kind+'__42';count=min(672,len(t));alerts=z[key][:count]>=float(z['threshold__'+key]);y=z['label1'][:count].astype(bool)
    fig,(ax,bx)=plt.subplots(2,1,figsize=(12,6),sharex=True,gridspec_kw={'height_ratios':[2,1]});ax.plot(t[:count],z['volume'][:count],color='#233e50',linewidth=.9,label='Observed volume');ax.scatter(t[:count][y],z['volume'][:count][y],color='#d26635',s=18,label='Inspector 1 anomaly');ax.set(ylabel='Volume',title=f'Illustrative held-out section {site} · {LABEL[kind]}');ax.legend(fontsize=9)
    bx.plot(t[:count],z[key][:count],color='#2f7189',linewidth=.8);bx.axhline(float(z['threshold__'+key]),color='#d26635',linestyle='--',label='Validation threshold');bx.scatter(t[:count][alerts],z[key][:count][alerts],color='#d26635',s=12);bx.set(ylabel='Anomaly score',xlabel='Source timestamp');bx.legend(fontsize=9);fig.autofmt_xdate();fig.tight_layout();fig.savefig(OUT/'example_detection.png',dpi=160);plt.close(fig)
    table=[]
    for k in order:table.append(dict(method=LABEL[k],F1_set1=final.loc[k,'f1'],F1_set2=final2.loc[k,'f1'],precision=final.loc[k,'precision'],recall=final.loc[k,'recall'],false_alerts_day=final.loc[k,'false_alerts_per_observed_day'],average_precision=final.loc[k,'average_precision']))
    td=pd.DataFrame(table);td.to_csv(OUT/'report_metrics.csv',index=False)
    bt=bench.groupby('model')[['fit_seconds','test_score_seconds','process_peak_rss_mb','serialized_model_bytes']].mean().reindex(ALL_IF).reset_index();bt['model']=bt.model.map(LABEL)
    plain=lambda df:df.to_html(index=False,border=0,float_format=lambda x:f'{x:.4f}')
    effect=effects.query("label_set=='label_set_1'")[['comparison','mean_f1_difference','ci95_low','ci95_high','fraction_sites_positive']]
    ns=normal.query("label_set=='label_set_1'")[['model','primary_f1','normal_only_f1','difference','ci95_low','ci95_high']].copy();ns['model']=ns.model.map(LABEL)
    primary=final.loc[PRIMARY];chosen=sel['demo_model'];rq1=effects.query("comparison=='context_full' and label_set=='label_set_1'").iloc[0];rq2=effects.query("comparison=='pca2_context' and label_set=='label_set_1'").iloc[0]
    findings=f'''Time-of-week residualisation changes matched full-window Isolation Forest F1 by {rq1.mean_f1_difference:+.4f} (95% site-bootstrap interval {rq1.ci95_low:+.4f} to {rq1.ci95_high:+.4f}). Two-component PCA changes the contextual IF result by {rq2.mean_f1_difference:+.4f} ({rq2.ci95_low:+.4f} to {rq2.ci95_high:+.4f}). These are empirical differences on this benchmark, not universal guarantees. Compression must therefore be justified by its measured accuracy and cost trade-off rather than assumed beneficial.'''
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Classical traffic anomaly detection · final results</title>
<style>body{{font:16px/1.65 system-ui,sans-serif;background:#edf2f5;color:#193247;margin:0}}main{{max-width:1100px;margin:30px auto;padding:38px;background:white;border-radius:14px}}h1{{font-size:38px;line-height:1.18}}h2{{margin-top:36px}}.lead{{font-size:20px}}.note{{background:#fff2e8;border-left:4px solid #d26635;padding:14px}}.scroll{{overflow:auto}}table{{border-collapse:collapse;width:100%;font-size:13px}}td,th{{padding:9px;text-align:left;border-bottom:1px solid #d9e1e7}}img{{width:100%;height:auto}}a{{color:#176681}}code{{background:#edf2f5;padding:2px 5px}}@media(max-width:650px){{main{{margin:8px;padding:18px}}h1{{font-size:28px}}}}</style><main>
<p>IFN737 classical implementation · new experiments completed November 2026</p><h1>Temporal context and PCA<br>for traffic-volume anomaly detection</h1>
<p class="lead">A matched empirical comparison on 147 AnoLT road sections, with 117 sections reserved from new global model selection and three chronological evaluation folds.</p>
<p class="note">This project implements the anomaly-detection research in the final 2C report and aligned 2B presentation. It is separate from the earlier SCATS next-count forecaster. These new results extend the historical six-site pilot; they are not backdated progress claims. The labels represent unusual volume patterns, not confirmed crashes.</p>
<p class="note">This report records the completed full local experiment. This source repository contains compact derived tables and figures; raw data, fitted weights and detailed score/cache arrays must be generated locally. Historical course PDFs/PPTX and upstream third-party scripts are not included. See README.md for the clean-clone workflow. Full-output verification requires complete reproduction.</p><h2>Answers to the research questions</h2><p>{findings}</p><p>The adapted Si-TDD-style baseline has the highest mean F1 in this comparison: <b>{final.loc['sitdd_adapted','f1']:.3f}</b>, compared with {final.loc['time_of_week_mad','f1']:.3f} for time-of-week MAD and {final.loc['if_context_full','f1']:.3f} for contextual full-window IF. The extra complexity of IF does not outperform the stronger contextual baselines here.</p><p>The locally reproducible example uses <b>{LABEL[chosen]}</b>, chosen among the four primary IF representations on development validation data. Its selection did not use final-site test results. All baselines and secondary PCA widths remain visible below, including methods that may outperform the example IF.</p>
<h2>Data, allocation and chronology</h2><p>The pinned AnoLT snapshot contains 147 road-section CSVs and 3,125,856 observations. All 147 Git object hashes and SHA-256 digests were verified. The earlier audit found 499 gaps longer than 15 minutes and 37,814 disagreements between inspector annotations. Valid zero counts are retained; windows crossing a timestamp discontinuity are excluded. Eight readings include the current observed interval and seven prior readings.</p>
<p>The six original pilot sections plus 24 seeded additional sections form the 30-site development group. The remaining 117 sections are excluded from new global hyperparameter selection. Earlier aggregate audit information was already available; raw final-site data are not claimed to have been wholly unseen. Allocation uses seed 2026 and is saved in <a href="protocol.json">protocol.json</a>. Opposite directions sharing an ID prefix can span allocation groups, so geographic independence is not established.</p>
<p>Fold endpoints for fit/validation/test are 40/55/70%, 55/70/85% and 70/85/100% of each section's raw ordered rows. Test periods are disjoint within a section. Each fold fits earlier local data and calibrates on local validation labels. Thus the evaluation transfers a fixed procedure to locally fitted sections; it does not test one shared set of weights or zero-shot transfer.</p>
<h2>Matched methods and calibration</h2><p>Global MAD, time-of-week MAD, two-component PCA reconstruction and an adapted Si-TDD-style same-slot nearest-neighbour score are included. The matched detector is Isolation Forest on standardised eight-reading windows, either full or PCA-compressed (2 primary; 4 and 6 sensitivity components), with and without training-derived weekday/quarter-hour median–MAD residualisation.</p>
<p>All transformations fit training data only. Primary fitting retains earlier anomalies. One shared max-samples value ({sel['max_samples']}) was selected from 128 and 256 on development validation F1 across the four primary representations, sites, folds and seeds. All forests use 100 trees and seeds 17, 42 and 91. The same setting is used for every representation. Si-TDD-style k={sel['sitdd_k']} was selected from the source algorithm's six candidate values. Its score definition was independently checked; our validation calibration and fallback rules differ from the paper's reported evaluation, so no exact paper-score replication is claimed.</p>
<p>Every site/fold/method/seed threshold maximises validation set-1 F1 with ties favouring fewer alerts. It is frozen for test labels from both inspectors. If validation contains no positive labels, no alerts are issued. Labels are not model inputs; threshold calibration is label-assisted. Predictions are scored pointwise with no point adjustment.</p>
<h2>Final-site detection results</h2><p>Values first average forest seeds and chronological folds within a section, then average the 117 sections equally. Baselines have no random-seed repetitions. Inspector set 2 reuses the exact set-1-calibrated thresholds. False alerts/day uses 96 eligible observations as one equivalent observed day; gaps are not invented exposure. Average precision is zero for a fold without positive labels.</p>
<div class="scroll">{plain(td)}</div><img src="results/final_f1.png" alt="Mean final-site F1 for all methods">
<h2>Paired representation effects and uncertainty</h2><p>The primary contrasts isolate context and two-component PCA within the same detector procedure. Paired F1 differences are computed after averaging folds and seeds within each section. A seeded 1,000-draw site bootstrap supplies percentile intervals. Multiple contrasts and spatial dependence limit inferential claims; these intervals are descriptive evidence, not proof of universal superiority. For the contextual two-component PCA contrast, the shared-ID-prefix interval spans zero even when the site-bootstrap interval does not. The size and certainty of that effect therefore depend on how related directions are grouped. Shared-ID-prefix cluster sensitivity is saved separately in <a href="results/paired_effects.csv">paired_effects.csv</a>.</p>
<div class="scroll">{plain(effect)}</div><img src="results/paired_effects.png" alt="Paired differences and site-bootstrap intervals"><img src="results/precision_recall.png" alt="Macro precision recall curves">
<p>Precision–recall curves are interpolated on a common recall grid, averaging folds/seeds within section and then sections. They are not a pooled ranking of incomparable cross-site raw scores. AP in the metrics table is averaged from per-evaluation scores rather than computed from the interpolated curve.</p>
<h2>Training contamination sensitivity</h2><p>The primary run retains earlier anomalous training observations. This separate sensitivity removes set-1 anomalous training rows and any eight-reading training window touching one, using seed 42, frozen global settings and the same validation rule. The paired primary reference also uses seed 42. This is an intentionally label-informed sensitivity analysis, not the default deployable training policy.</p><div class="scroll">{plain(ns)}</div>
<h2>Runtime, model size and memory</h2><p>The following serial benchmark runs each representation in a fresh subprocess on the same 0185-E final-fold inputs, repeating seeds 17, 42 and 91. Fit time includes scaling, PCA where applicable and forest fitting. Context/window preparation is measured separately and excluded from these fit times. Test scoring uses identical eligible observations. Peak RSS includes the interpreter and libraries; it is not estimator-only allocation. Serialized size is an additional compactness measure. Small timing differences should not be overinterpreted.</p><div class="scroll">{plain(bt)}</div><p>Machine: {html.escape(platform.platform())}. Exact versions and per-run timings are in <a href="environment-lock.txt">environment-lock.txt</a> and <a href="results/isolated_benchmark.csv">isolated_benchmark.csv</a>. Main parallel-worker timings are diagnostic and should not replace this isolated comparison. Baseline diagnostic score timings cover all eligible windows, while IF diagnostics cover validation and test windows, so those columns are not cross-family cost comparisons. The dedicated benchmark uses OS peak RSS on macOS/Linux and a sampled 5 ms approximation on systems without the Unix resource module, recorded in rss_measurement.</p>
<h2>False-alert analysis and a held-out example</h2><p>Error tables separate zero/low/high counts, overnight observations, annotation disagreement and observations near gaps. Categories overlap. Inspect <a href="results/error_groups.csv">error_groups.csv</a> and per-section records before interpreting aggregate precision. Fold and seed stability are retained in <a href="results/fold_metrics.csv">fold_metrics.csv</a> and <a href="results/seed_sensitivity.csv">seed_sensitivity.csv</a>. Episode descriptors measure eligible labelled runs at 15-minute resolution; they do not alter pointwise results or establish crash-response delay.</p><img src="results/example_detection.png" alt="Observed counts labels and anomaly scores for a deterministically selected held-out section">
<h2>Scope achieved and remaining limits</h2><p>The classical pipeline, matched context/PCA comparison, expanded site/period evaluation, annotation and contamination sensitivity, paired uncertainty, runtime/memory measurement and reusable example model are implemented and executed. The earlier report's RQ2 is now tested directly. Four- and six-component PCA are secondary checks; a negative compression result remains a research finding.</p>
<p>Selected procedural details were fixed here because the earlier report left them open: 100-tree forests, two max-sample candidates, three seeds and deterministic additional-site selection. No supervisor approval is implied. Context and threshold estimates may drift, geographic dependence remains possible, and benchmark labels do not identify anomaly causes. No external-city dataset, live monitoring, verified crash association, spatial model or quantum layer was evaluated. Those remain separate extensions after this classical baseline.</p>
<h2>Recheck on 19 November 2026</h2><p>The expanded source-to-score audit reproduced 30,312 metric rows and 108 fresh fits across pilot, development and final sections. All 25 regression tests passed. Input validation now rejects a known section/model mismatch, resumed jobs verify their inputs and output hashes, and the Unix-only import was removed from the portable runner. Detection results and frozen choices are unchanged. The no-resource memory path was exercised on this Mac; a full Windows-device run is not claimed. See <a href="Recheck_2026-11-19.md">the recheck record</a> for scope and evidence. In the full local package, cache sidecars for the original jobs were bound after this audit and labelled accordingly; those sidecars are excluded from Git.</p><h2>Use, reproduce and inspect</h2><p>See <a href="README.md">README.md</a> for setup, scoring, training another section and full reproduction. The <a href="experiment.ipynb">notebook</a> walks through the results. Source provenance and choices are frozen in <a href="protocol.json">protocol.json</a> and <a href="selected_parameters.json">selected_parameters.json</a>. Verification is recorded in <a href="results/verification.json">verification.json</a>. Locally training the example creates an illustrative calibrated detector; binary weights are excluded from Git and anomaly scores are not probabilities.</p>
<h2>Attribution</h2><p>AnoLT data and algorithm reference: Taheri Sarteshnizi et al. (2026), <a href="https://doi.org/10.1016/j.trc.2026.105536">Transportation Research Part C 184, 105536</a>; <a href="https://github.com/imaantaheri/AnoLT/tree/d2e927425b40235d881905ba6881112bcc017e43">pinned repository</a>. The <a href="https://github.com/imaantaheri/AnoLT/blob/d2e927425b40235d881905ba6881112bcc017e43/data_to_score/Si-TDD.py">original upstream Si-TDD script</a> is linked rather than copied into this repository; upstream terms continue to apply. Implementation uses <a href="https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.IsolationForest.html">scikit-learn Isolation Forest</a> and <a href="https://scikit-learn.org/stable/modules/generated/sklearn.decomposition.PCA.html">PCA</a>. Earlier IFN737 reports and presentation supplied the research plan. OpenAI Codex assisted with implementation, execution, checking and reporting. No quantum components are used.</p></main></html>'''
    (ROOT/'report.html').write_text(page)
    (ROOT/'Research_Findings.md').write_text('# Completed classical anomaly-detection experiment\n\n'+findings+'\n\n'+'Detailed metrics: [results/report_metrics.csv](results/report_metrics.csv)'+ '\n\nSee report.html for the protocol, uncertainty, sensitivity, runtime and limits. New experiments extend the historical progress reports; earlier documents were not backdated or rewritten.\n')
    print('Saved report and figures',flush=True)
if __name__=='__main__':main()
